#include <stdio.h>

#define MAX_EVENTS 10
#define MAX_LISTENERS 5

typedef struct {
    void (*cbs[MAX_EVENTS][MAX_LISTENERS])(int, void*);
    int counts[MAX_EVENTS];
} EventBus;

void eb_init(EventBus *eb) { for (int i=0;i<MAX_EVENTS;i++) eb->counts[i]=0; }

void eb_on(EventBus *eb, int event, void (*cb)(int, void*)) {
    if (eb->counts[event] < MAX_LISTENERS)
        eb->cbs[event][eb->counts[event]++] = cb;
}

void eb_emit(EventBus *eb, int event, void *data) {
    for (int i = 0; i < eb->counts[event]; i++)
        eb->cbs[event][i](event, data);
}

void on_login(int e, void *d) { printf("Login event: %s\n", (char*)d); }
void on_logout(int e, void *d) { printf("Logout event: %s\n", (char*)d); }

int main() {
    EventBus eb;
    eb_init(&eb);
    eb_on(&eb, 1, on_login);
    eb_on(&eb, 2, on_logout);
    eb_emit(&eb, 1, "User1");
    eb_emit(&eb, 2, "User1");
    return 0;
}
